import{_ as a,o as e,c as t,a2 as r}from"./chunks/framework.D21_4UK8.js";const g=JSON.parse('{"title":"🎙️ オーディオ・エンジニアリングマスターガイド：1x12 Hardwood Cab Lab & Studio Mic Mixer","description":"","frontmatter":{},"headers":[],"relativePath":"ja/audio-mics-guide.md","filePath":"ja/audio-mics-guide.md"}'),s={name:"ja/audio-mics-guide.md"};function n(i,o,d,l,c,p){return e(),t("div",null,[...o[0]||(o[0]=[r(`<h1 id="🎙️-オーディオ・エンジニアリングマスターガイド-1x12-hardwood-cab-lab-studio-mic-mixer" tabindex="-1">🎙️ オーディオ・エンジニアリングマスターガイド：1x12 Hardwood Cab Lab &amp; Studio Mic Mixer <a class="header-anchor" href="#🎙️-オーディオ・エンジニアリングマスターガイド-1x12-hardwood-cab-lab-studio-mic-mixer" aria-label="Permalink to &quot;🎙️ オーディオ・エンジニアリングマスターガイド：1x12 Hardwood Cab Lab &amp; Studio Mic Mixer&quot;">​</a></h1><h3 id="evm-12lコーン音響物理、位相科学、デュアルマイキング、1トラックで完結するステレオ録音の秘密" tabindex="-1">EVM-12Lコーン音響物理、位相科学、デュアルマイキング、1トラックで完結するステレオ録音の秘密 <a class="header-anchor" href="#evm-12lコーン音響物理、位相科学、デュアルマイキング、1トラックで完結するステレオ録音の秘密" aria-label="Permalink to &quot;EVM-12Lコーン音響物理、位相科学、デュアルマイキング、1トラックで完結するステレオ録音の秘密&quot;">​</a></h3><p><strong>TattooYou Vintage Amplifier &amp; Studio Suite | Main St Audio Labs</strong></p><hr><h2 id="📖-序文-伝説のアンプを録音する芸術" tabindex="-1">📖 序文：伝説のアンプを録音する芸術 <a class="header-anchor" href="#📖-序文-伝説のアンプを録音する芸術" aria-label="Permalink to &quot;📖 序文：伝説のアンプを録音する芸術&quot;">​</a></h2><p>1970年代後半から1980年代初頭の伝説的なスタジオセッションにおいて、エレキギターのマイキングは単一のマイクをアンプの前に置くだけのものではなくなりました。当時の名エンジニアたちは、<strong>無垢材（Hardwood）キャビネットの響き</strong>、<strong>大出力ドライバーによる濁りのない忠実度</strong>、そして<strong>完全な位相整合（Phase Alignment）によるデュアルマイキング</strong>の相乗効果こそが、スピーカーから飛び出す巨大で立体的なギターサウンドの真の秘密であることを発見しました。</p><p><strong>TattooYou</strong>に搭載された<strong>1x12 Hardwood Cab Lab</strong>は、このスタジオ環境を精密に再現します。</p><hr><h2 id="🔊-1-evm-12lドライバーとhardwoodキャビネットの音響物理" tabindex="-1">🔊 1. EVM-12LドライバーとHardwoodキャビネットの音響物理 <a class="header-anchor" href="#🔊-1-evm-12lドライバーとhardwoodキャビネットの音響物理" aria-label="Permalink to &quot;🔊 1. EVM-12LドライバーとHardwoodキャビネットの音響物理&quot;">​</a></h2><h3 id="a-スピーカー歪みゼロ-zero-speaker-breakup-と無限のヘッドルーム" tabindex="-1">A. スピーカー歪みゼロ（Zero Speaker Breakup）と無限のヘッドルーム <a class="header-anchor" href="#a-スピーカー歪みゼロ-zero-speaker-breakup-と無限のヘッドルーム" aria-label="Permalink to &quot;A. スピーカー歪みゼロ（Zero Speaker Breakup）と無限のヘッドルーム&quot;">​</a></h3><p>伝統的なギター用スピーカー（25W〜30Wのペーパーコーン）は、パワーを入れるとコーン紙自体が歪み、高域に粗いサチュレーションを生み出し、低域を圧縮します。</p><p><strong>EVM-12L</strong>（200W〜300W定格、7.5kgの大型セラミックマグネット、アルミダイキャストフレーム）は、それとは正反対の設計思想で作られています：</p><ul><li><strong>純粋な真空管ダイナミクス：</strong> スピーカーコーン自体が音を濁らせません。耳にする倍音とサチュレーションは、<strong>6L6真空管と&#39;78 Mark Iプリアンプ回路そのものの純粋なサウンド</strong>です。</li><li><strong>抜群の弦分離感：</strong> 複雑なコードワークやキース・リチャーズ特有のオープンGチューニングでも、すべての弦の音が混ざり合わずにクリアに響きます。</li></ul><h3 id="b-バスレフポート付き無垢材-hardwood-キャビネット" tabindex="-1">B. バスレフポート付き無垢材（Hardwood）キャビネット <a class="header-anchor" href="#b-バスレフポート付き無垢材-hardwood-キャビネット" aria-label="Permalink to &quot;B. バスレフポート付き無垢材（Hardwood）キャビネット&quot;">​</a></h3><p>一般的なオープンバックのコンボキャビネットとは異なり、チューニングされた前面バスレフポートを備えた無垢材キャビネットを採用：</p><ul><li><strong>タイトで正確な低域：</strong> <strong>80 Hz〜160 Hz</strong>のエネルギーをタイトに引き締め、ブーミーな低音の濁りを徹底的に排除します。</li></ul><hr><h2 id="🎯-2-マイキング・マトリックス" tabindex="-1">🎯 2. マイキング・マトリックス <a class="header-anchor" href="#🎯-2-マイキング・マトリックス" aria-label="Permalink to &quot;🎯 2. マイキング・マトリックス&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                  ┌──────────────────────────────────────────────┐</span></span>
<span class="line"><span>                  │                 スピーカーコーン               │</span></span>
<span class="line"><span>                  │                                              │</span></span>
<span class="line"><span>                  │      ( -3 )      ( -2 )      ( -1 )   ( 0 )  │</span></span>
<span class="line"><span>                  │      外周        コーン面   キャップエッジ  センター│</span></span>
<span class="line"><span>                  │     (Dark)       (Warm)     (Sweet)   (Bright)│</span></span>
<span class="line"><span>                  │                                              │</span></span>
<span class="line"><span>                  │  [ PORT ]  &lt;─── (バスレフポート)              │</span></span>
<span class="line"><span>                  └──────────────────────────────────────────────┘</span></span></code></pre></div><ul><li><strong><code>0: Direct</code>（センター）:</strong> 鋭いピッキングアタックと輝くような高域（4 kHz〜8 kHz強調）。</li><li><strong><code>+1: Edge</code>（キャップエッジ）:</strong> 抜けの良いクラシックロックのリズムバイト。</li><li><strong><code>-1: Sweet</code>（スイートスポット）:</strong> <strong>スタジオ基準の黄金バランス。</strong> あらゆるジャンルに対応する推奨初期設定。</li><li><strong><code>-2: Warm</code>（コーン面）:</strong> 滑らかな高域と丸みのある中域。ブライトなシングルコイルに最適。</li><li><strong><code>-3: Dark</code>（外周）:</strong> 太くダークなウォームトーン。</li><li><strong><code>Port: Bass</code>（バスレフ）:</strong> 80 Hz〜160 Hzの胸に響く4x12スタイルの重低音パンチ。</li><li><strong><code>Room 3D</code>（スタジオ空間）:</strong> 自然な反射音と空気感をもたらすステレオペア。</li></ul><hr><h2 id="🤯-3-1トラックで完結するワイドステレオ-トラック複製の省略" tabindex="-1">🤯 3. 1トラックで完結するワイドステレオ（トラック複製の省略） <a class="header-anchor" href="#🤯-3-1トラックで完結するワイドステレオ-トラック複製の省略" aria-label="Permalink to &quot;🤯 3. 1トラックで完結するワイドステレオ（トラック複製の省略）&quot;">​</a></h2><h3 id="❌-従来の手法-dawトラックの複製とフェイズの崩壊" tabindex="-1">❌ 従来の手法（DAWトラックの複製とフェイズの崩壊） <a class="header-anchor" href="#❌-従来の手法-dawトラックの複製とフェイズの崩壊" aria-label="Permalink to &quot;❌ 従来の手法（DAWトラックの複製とフェイズの崩壊）&quot;">​</a></h3><p>従来、ステレオ感を出すためにはトラックを複製してディレイをかけたり、疑似ステレオプラグインを使う必要があり、モノラル再生時に音が消える位相問題（コムフィルター）が発生していました。</p><h3 id="✅-tattooyouの-stereo-spread-3d" tabindex="-1">✅ TattooYouの <code>STEREO SPREAD 3D</code> <a class="header-anchor" href="#✅-tattooyouの-stereo-spread-3d" aria-label="Permalink to &quot;✅ TattooYouの \`STEREO SPREAD 3D\`&quot;">​</a></h3><p>DAW上で<strong>1つのステレオトラック</strong>を用意し、<strong><code>STEREO SPREAD 3D</code></strong> をONにするだけです：</p><ul><li><strong>Mic 1（左ch）に <code>57 L (-1) Sweet</code></strong>、<strong>Mic 2（右ch）に <code>57 R (-1) Sweet</code></strong> を割り当て、<strong>Blendを50%</strong> に設定。</li><li>スピーカー左右の微細な音響特性の違いを利用し、<strong>トラックを複製することなく、超広大なアナログステレオ空間</strong>が瞬時に完成します。</li></ul><hr><h2 id="🏆-4-スタジオ・リファレンス・プリセット" tabindex="-1">🏆 4. スタジオ・リファレンス・プリセット <a class="header-anchor" href="#🏆-4-スタジオ・リファレンス・プリセット" aria-label="Permalink to &quot;🏆 4. スタジオ・リファレンス・プリセット&quot;">​</a></h2><ol><li>🎸 <strong>Studio Standard:</strong> <code>57 L Sweet</code> + <code>87 L Direct</code>（Blend 30%, Mono）— 王道のモダンロックサウンド。</li><li>🥊 <strong>Heavy Punch:</strong> <code>57 L Sweet</code> + <code>57 L BassPort</code>（Blend 25%, Mono）— 4x12級の重低音リフ。</li><li>🌌 <strong>Live Room 3D:</strong> <code>57 L Sweet</code> + <code>87 Room L 3D</code>（Blend 25%, Stereo）— リアルなスタジオ空間。</li><li>🎧 <strong>Wide Double Track:</strong> <code>57 L Sweet</code> + <code>57 R Sweet</code>（Blend 50%, Stereo）— 1トラック完結のウルトラワイドステレオ。</li><li>⚡ <strong>Solo 57 Classic:</strong> <code>57 L Sweet</code>（Mono）— ダイレクトでパンチのある王道トーン。</li><li>✨ <strong>Solo 87 Hi-Fi:</strong> <code>87 L Direct</code>（Mono）— 最高峰のハイファイ・スタジオクオリティ。</li></ol>`,30)])])}const u=a(s,[["render",n]]);export{g as __pageData,u as default};
